package shop.jitustore.jspay;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.util.Base64;

/** Home screen ke 4 banner ki apni banayi hui drawing (art only; text app mein upar likha jaata hai). */
final class Art {
    private static final Bitmap[] cache = new Bitmap[4];
    private static final String A0 = "";
    private static final String A1 = "";
    private static final String A2 = "";
    private static final String A3 = "";

    static Bitmap get(int i) {
        try {
            if (i < 0 || i > 3) return null;
            if (cache[i] == null) {
                String d = i == 0 ? A0 : i == 1 ? A1 : i == 2 ? A2 : A3;
                byte[] raw = Base64.decode(d, Base64.DEFAULT);
                cache[i] = BitmapFactory.decodeByteArray(raw, 0, raw.length);
            }
            return cache[i];
        } catch (Throwable e) { return null; }
    }
}
